/**
 * OWASP LLM Top 10 Compliance Dashboard
 *
 * Displays security posture across OWASP LLM Top 10 categories.
 * Pulls live `pnpm audit --json` summary from
 * `/data/security/audit.json` (generated by
 * `scripts/gen-security-audit.mjs` at build time) so the dashboard
 * reflects real dependency CVE counts, not just the OWASP category checklist.
 *
 * Styled via Tailwind to match the MapleSpike portal design system.
 */
import * as React from "react";

interface CheckItem {
  description: string;
  status: "pass" | "fail" | "partial" | "na";
}

interface OWASPCategory {
  id: string;
  name: string;
  description: string;
  severity: "Critical" | "High" | "Medium" | "Low";
  status: "pass" | "fail" | "partial";
  checkItems: CheckItem[];
}

interface AuditSummary {
  total: number;
  critical: number;
  high: number;
  moderate: number;
  low: number;
  info: number;
}

interface AuditAdvisory {
  id: string;
  package: string;
  severity: "critical" | "high" | "moderate" | "low" | "info";
  title: string;
  url?: string;
}

interface AuditMeta {
  source: "live" | "static";
  generatedAgeSeconds: number;
  fallbackReason?: string;
}

interface AuditPayload {
  generatedAt: string;
  summary: AuditSummary;
  top: AuditAdvisory[];
  note?: string;
  _meta?: AuditMeta;
}

const statusMeta = {
  pass: { label: "Pass", color: "bg-green-500/15 text-green-400 border-green-500/25" },
  fail: { label: "Fail", color: "bg-red-500/15 text-red-400 border-red-500/25" },
  partial: { label: "Partial", color: "bg-amber-500/15 text-amber-400 border-amber-500/25" },
} as const;

const severityMeta = {
  Critical: "bg-red-600 text-white",
  High: "bg-orange-500 text-white",
  Medium: "bg-amber-500 text-white",
  Low: "bg-green-600 text-white",
} as const;

const cveSeverityMeta = {
  critical: { label: "Critical", color: "bg-red-600 text-white" },
  high: { label: "High", color: "bg-orange-500 text-white" },
  moderate: { label: "Moderate", color: "bg-amber-500 text-white" },
  low: { label: "Low", color: "bg-green-600 text-white" },
  info: { label: "Info", color: "bg-slate-500 text-white" },
} as const;

const checkIcon: Record<string, string> = {
  pass: "✅",
  fail: "❌",
  partial: "⚠️",
  na: "➖",
};

