const EMPTY_AUDIT: AuditPayload = {
  generatedAt: new Date(0).toISOString(),
  summary: { total: 0, critical: 0, high: 0, moderate: 0, low: 0, info: 0 },
  top: [],
};

function formatAge(seconds: number): string {
  if (seconds < 0) return "just now";
  if (seconds < 60) return `${seconds}s ago`;
  const m = Math.floor(seconds / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  return `${d}d ago`;
}

/**
 * Resolve the API URL for live audit calls. Mirrors the pattern in
 * `public/config.js` which sets `window.MAPLESPIKE.apiBase`. Falls
 * back to a same-origin path for setups where the portal proxies
 * /v1/* to the api-server (e.g., production via Caddy).
 */
function resolveAuditEndpoint(): string {
  if (typeof window === "undefined") return "/v1/security/audit-summary";
  const w = window as unknown as {
    MAPLESPIKE?: { apiBase?: string };
    location: Location;
  };
  const injected = typeof w.MAPLESPIKE?.apiBase === "string" ? w.MAPLESPIKE.apiBase.trim() : "";
  if (injected) return injected.replace(/\/$/, "") + "/v1/security/audit-summary";
  return `${w.location.protocol}//${w.location.hostname}:8082/v1/security/audit-summary`;
}

/**
 * Fetches `/v1/security/audit-summary`, which serves the build-time snapshot
 * from `scripts/gen-security-audit.mjs`. Falls back to
 * `/data/security/audit.json` when the API is unreachable. The badge shows
 * the snapshot age so a build-time file is not presented as a live scan.
 */
function DependencySecurityPanel() {
  const [audit, setAudit] = React.useState<AuditPayload>(EMPTY_AUDIT);
  const [loadState, setLoadState] = React.useState<"loading" | "ok" | "missing" | "error">(
    "loading"
  );
  const [fetchSource, setFetchSource] = React.useState<"live" | "static" | "stub" | null>(
    null
  );

  React.useEffect(() => {
    let cancelled = false;

    async function loadLive(): Promise<AuditPayload | null> {
      try {
        const res = await fetch(resolveAuditEndpoint(), { cache: "no-store" });
        if (!res.ok) return null;
        return (await res.json())?.data as AuditPayload | null;
      } catch {
        return null;
      }
    }

    async function loadStatic(): Promise<AuditPayload | null> {
      try {
        const res = await fetch("/data/security/audit.json", { cache: "no-store" });
        if (!res.ok) return null;
        return (await res.json()) as AuditPayload;
      } catch {
        return null;
      }
    }

    async function load() {
      // Try the live endpoint first.
      const live = await loadLive();
      if (cancelled) return;
      if (live) {
        setAudit(live);
        setFetchSource(live._meta?.source ?? "static");
        setLoadState("ok");
        return;
      }

      // Fall back to the build-time static snapshot.
      const staticData = await loadStatic();
      if (cancelled) return;
      if (staticData) {
        setAudit({ ...staticData, _meta: { source: "static", generatedAgeSeconds: staticData._meta?.generatedAgeSeconds ?? 0 } });
        setFetchSource("static");
        setLoadState("ok");
        return;
      }

      setFetchSource("stub");
      setLoadState("missing");
    }
    void load();

    return () => {
      cancelled = true;
    };
  }, []);

  const s = audit.summary;
  const headline =
    loadState === "ok"
      ? s.total === 0
        ? "No known CVEs in the dependency tree."
        : `${s.total} open advisories across ${s.critical + s.high} critical/high packages.`
      : loadState === "missing"
        ? "Live audit data hasn't been generated yet. Run `pnpm gen:security` or `pnpm gen:all`."
        : loadState === "loading"
          ? "Loading latest dep audit…"
          : "Couldn't load audit.json (network or parse error).";

  const headlineClass =
    loadState === "ok"
      ? s.critical + s.high === 0
        ? "border-green-500/30 bg-green-500/10 text-green-300"
        : "border-red-500/30 bg-red-500/10 text-red-300"
      : "border-border bg-card text-muted-foreground";

  const ageSeconds =
    audit._meta?.generatedAgeSeconds ??
    Math.floor((Date.now() - new Date(audit.generatedAt).getTime()) / 1000);

  const sourceBadge =
    fetchSource === "live"
      ? { label: `LIVE · ${formatAge(ageSeconds)}`, class: "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" }
      : fetchSource === "static"
        ? { label: `BUILD-TIME SNAPSHOT · ${formatAge(ageSeconds)}`, class: "border-amber-500/40 bg-amber-500/15 text-amber-300" }
        : { label: "STUB", class: "border-border bg-muted text-muted-foreground" };

  return (
    <section className="mb-10 rounded-xl border bg-card/40 p-6">
      {/* Header */}
      <div className="mb-4 flex flex-wrap items-baseline justify-between gap-3">
        <div>
          <div className="flex flex-wrap items-center gap-2">
            <h2 className="text-xl font-bold tracking-tight">
              Live Dependency <span className="text-gradient">Security</span>
            </h2>
            <span
              className={`rounded-md border px-2 py-0.5 text-xs font-bold uppercase tracking-wider ${sourceBadge.class}`}
              title={
                audit._meta?.fallbackReason ??
                audit.note ??
                "Build-time snapshot from /v1/security/audit-summary"
              }
            >
              {sourceBadge.label}
            </span>
          </div>
          <p className="mt-1 text-sm text-muted-foreground">
            Source: <code className="font-mono text-xs">pnpm audit --json</code>{" "}
            <span className="opacity-70">
              (snapshot served by{" "}
              <code className="font-mono text-xs">/v1/security/audit-summary</code>
              {". Refresh with "}
              <code className="font-mono text-xs">node scripts/gen-security-audit.mjs</code>
              .)
            </span>
          </p>
        </div>
        {loadState === "ok" && (
          <p className="text-xs text-muted-foreground">
            Updated{" "}
            <time dateTime={audit.generatedAt}>
              {new Date(audit.generatedAt).toLocaleString("en-CA")}
            </time>
          </p>
        )}
      </div>

      {/* Headline banner */}
      <div className={`mb-5 rounded-lg border p-3 text-sm ${headlineClass}`}>
        {headline}
        {(audit.note || audit._meta?.fallbackReason) && (
          <p className="mt-1 text-xs opacity-80">
            {audit._meta?.fallbackReason ? `note: ${audit._meta.fallbackReason}` : `note: ${audit.note}`}
          </p>
        )}
      </div>

      {/* Severity counts */}
      {loadState === "ok" && (
        <>
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-5">
            {(
              [
                ["Critical", s.critical, "critical"],
                ["High", s.high, "high"],
                ["Moderate", s.moderate, "moderate"],
                ["Low", s.low, "low"],
                ["Info", s.info, "info"],
              ] as const
            ).map(([label, count, key]) => (
              <div
                key={label}
                className="flex flex-col items-start rounded-lg border bg-background/60 p-3"
              >
                <span
                  className={`mb-1 rounded-md px-2 py-0.5 text-xs font-bold uppercase tracking-wider ${
                    cveSeverityMeta[key].color
                  }`}
                >
                  {label}
                </span>
                <span className="text-2xl font-bold tracking-tight">{count}</span>
              </div>
            ))}
          </div>

          {/* Top advisories */}
          {audit.top.length > 0 && (
            <div className="mt-5">
              <h3 className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Top advisories ({audit.top.length})
              </h3>
              <ul className="space-y-2">
                {audit.top.map((adv) => {
                  const sev = cveSeverityMeta[adv.severity] ?? cveSeverityMeta.info;
                  return (
                    <li
                      key={adv.id}
                      className="flex flex-wrap items-center gap-3 rounded-lg border border-border/60 bg-background/50 px-3.5 py-2.5"
                    >
                      <span
                        className={`rounded-md px-2 py-0.5 text-xs font-bold uppercase tracking-wider ${sev.color}`}
                      >
                        {sev.label}
                      </span>
                      <code className="rounded bg-muted px-1.5 py-0.5 font-mono text-xs">
                        {adv.package}
                      </code>
                      <span className="flex-1 text-sm text-foreground/80">
                        {adv.title}
                      </span>
                      {adv.url && (
                        <a
                          href={adv.url}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="text-xs text-primary hover:underline"
                        >
                          Advisory →
                        </a>
                      )}
                    </li>
                  );
                })}
              </ul>
            </div>
          )}
        </>
      )}
    </section>
  );
}

import { createI18n } from "@maplespike/i18n";
import type { Locale } from "@maplespike/i18n";

export default function OwaspDashboard({ lang: propLang }: { lang?: Locale }) {
  const lang = propLang || (typeof window !== "undefined" ? ((window as unknown as Record<string, string>).__LANG as Locale || "en") : "en");
  const i18n = createI18n(lang);
  const passCount = owaspCategories.filter((c) => c.status === "pass").length;
  const partialCount = owaspCategories.filter((c) => c.status === "partial").length;
  const failCount = owaspCategories.filter((c) => c.status === "fail").length;
  const criticalCount = owaspCategories.filter(
    (c) => c.severity === "Critical" && c.status !== "pass"
  ).length;
  const highCount = owaspCategories.filter(
    (c) => c.severity === "High" && c.status !== "pass"
  ).length;

  return (
    <div className="mx-auto max-w-5xl">
      {/* Header */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">
          OWASP <span className="text-gradient">Compliance</span>
        </h1>
        <p className="mt-1.5 text-muted-foreground">
          Security posture assessment based on OWASP Top 10 for LLM Applications (2023)
        </p>
      </div>

      {/* Summary Cards */}
      <div className="mb-8 grid grid-cols-2 gap-4 sm:grid-cols-4">
        {[
          { label: "Total Categories", value: owaspCategories.length, color: "text-foreground" },
          { label: "Passing", value: passCount, color: "text-green-400" },
          { label: "Partial", value: partialCount, color: "text-amber-400" },
          { label: "Failing", value: failCount, color: "text-red-400" },
        ].map((s) => (
          <div key={s.label} className="rounded-xl border bg-card p-5">
            <div className="text-sm text-muted-foreground">{s.label}</div>
            <div className={`mt-1 text-3xl font-bold tracking-tight ${s.color}`}>{s.value}</div>
          </div>
        ))}
      </div>

      {/* Severity Alert */}
      {(criticalCount > 0 || highCount > 0) && (
        <div className="mb-8 rounded-xl border border-red-500/30 bg-red-500/10 p-4">
          <h2 className="text-lg font-semibold text-red-300">⚠️ Attention Required</h2>
          <ul className="mt-1 list-inside list-disc space-y-1 text-sm text-red-200/80">
            {criticalCount > 0 && (
              <li>{criticalCount} Critical severity item(s) need immediate action</li>
            )}
            {highCount > 0 && (
              <li>{highCount} High severity item(s) should be addressed soon</li>
            )}
          </ul>
        </div>
      )}

      {/* Live dependency CVE panel */}
      <DependencySecurityPanel />

      {/* Categories */}
      <div className="space-y-5">
        {owaspCategories.map((cat) => (
          <div key={cat.id} className="rounded-xl border bg-card p-6">
            {/* Head */}
            <div className="mb-4 flex flex-wrap items-start justify-between gap-4">
              <div className="flex-1">
                <div className="flex flex-wrap items-center gap-3">
                  <h3 className="text-xl font-semibold">
                    {cat.id}: {cat.name}
                  </h3>
                  <span
                    className={`rounded-md px-2.5 py-0.5 text-xs font-bold uppercase tracking-wider ${
                      severityMeta[cat.severity]
                    }`}
                  >
                    {cat.severity}
                  </span>
                  <span
                    className={`rounded-md px-2.5 py-0.5 text-xs font-bold uppercase tracking-wider ${
                      statusMeta[cat.status].color
                    }`}
                  >
                    {statusMeta[cat.status].label}
                  </span>
                </div>
                <p className="mt-1.5 text-sm leading-relaxed text-muted-foreground">
                  {cat.description}
                </p>
              </div>
            </div>

            {/* Checklist */}
            <div>
              <h4 className="mb-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Checklist ({cat.checkItems.length} items)
              </h4>
              <div className="space-y-1.5">
                {cat.checkItems.map((item, idx) => (
                  <div
                    key={idx}
                    className="flex items-center gap-3 rounded-lg border border-border/60 bg-background/50 px-3.5 py-2.5"
                  >
                    <span className="text-base">{checkIcon[item.status] || "➖"}</span>
                    <span className="text-sm text-foreground/80">{item.description}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Footer */}
      <footer className="mt-12 border-t border-border/60 pt-6">
        <p className="text-sm text-muted-foreground">
          Last updated: {new Date().toLocaleDateString("en-CA")}
        </p>
        <p className="mt-0.5 text-sm text-muted-foreground">
          Reference:{" "}
          <a
            href="https://owasp.org/www-project-top-10-for-large-language-model-applications/"
            target="_blank"
            rel="noopener noreferrer"
            className="text-primary hover:underline"
          >
            OWASP Top 10 for Large Language Model Applications
          </a>
        </p>
      </footer>
    </div>
  );
}
